#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1e9 + 7;

int main() {
  int n, k;
  cin >> n >> k;

  vector<int> a(n);
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }

  vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
  dp[0][0] = 1;

  for (int i = 1; i <= n; ++i) {
    for (int j = 0; j <= k; ++j) {
      for (int x = 0; x <= min(j, a[i - 1]); ++x) {
        dp[i][j] = (dp[i][j] + dp[i - 1][j - x]) % MOD;
      }
    }
  }

  cout << dp[n][k] << endl;

  return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

long long sum_digits(long long n) {
    long long sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

bool is_snuke_number(long long n) {
    for (long long m = n + 1; m < n + 1000; ++m) {
        if (m > 1000000000000000) break; 
        if ((double)n / sum_digits(n) > (double)m / sum_digits(m)) {
            return false;
        }
    }
    return true;
}

int main() {
    int k;
    cin >> k;

    vector<long long> snuke_numbers;
    long long num = 1;
    while (snuke_numbers.size() < k) {
        if (is_snuke_number(num)) {
            snuke_numbers.push_back(num);
        }
        num++;
    }

    for (int i = 0; i < k; ++i) {
        cout << snuke_numbers[i] << endl;
    }

    return 0;
}

