      if ((long long)a[perm[i]] * a[perm[i + 1]] % 4 != 0) {
        valid = false;
        break;
      }
    }
    if (valid) {
      possible = true;
      break;
    }
  } while (next_permutation(perm.begin(), perm.end()));

  if (possible) {
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }

  return 0;
}

