        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    auto bfs = [&](int start_node) {
        vector<int> dist(n + 1, -1);
        vector<int> farthest_nodes;
        int max_dist = -1;

        vector<bool> visited(n + 1, false);
        vector<int> q;
        q.push_back(start_node);
        dist[start_node] = 0;
        visited[start_node] = true;

        int head = 0;
        while (head < q.size()) {
            int u = q[head++];
            for (auto& edge : adj[u]) {
                int v = edge.first;
                int w = edge.second;
                if (!visited[v]) {
                    visited[v] = true;
                    dist[v] = dist[u] + w;
                    q.push_back(v);
                }
            }
        }

        for (int i = 1; i <= n; ++i) {
            if (dist[i] > max_dist) {
                max_dist = dist[i];
                farthest_nodes.clear();
                farthest_nodes.push_back(i);
            } else if (dist[i] == max_dist) {
                farthest_nodes.push_back(i);
            }
        }

        return make_pair(max_dist, farthest_nodes);
    };

    vector<vector<int>> farthest_monasteries(m);
    for (int i = 0; i < m; ++i) {
        auto result = bfs(monasteries[i]);
