using namespace std;

bool is_tolerable(const string& s, int p) {
    for (int i = 0; i < s.length(); ++i) {
        if (s[i] > 'a' + p - 1) {
            return false;
        }
    }
    for (int i = 0; i < s.length() - 1; ++i) {
        if (s[i] == s[i + 1]) {
            return false;
        }
    }
    for (int i = 0; i < s.length() - 2; ++i) {
        if (s[i] == s[i + 2]) {
            return false;
        }
    }
    return true;
}

