        string goal_str = "";
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                start_str += to_string(start[i][j]);
                goal_str += to_string(goal[i][j]);
            }
        }

        if (start_str == goal_str) {
            cout << 0 << endl;
            continue;
        }

        map<string, int> dist;
        queue<string> q;

        dist[start_str] = 0;
        q.push(start_str);

        while (!q.empty()) {
            string current = q.front();
            q.pop();

            int zero_row, zero_col;
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 3; ++j) {
                    if (current[i * 3 + j] == '0') {
                        zero_row = i;
                        zero_col = j;
