        int covered_segments = 0;
        for (int i = 0; i < n; ++i) {
            if (segments[i].first <= event && event <= segments[i].second) {
                covered_segments++;
            }
        }
        if (covered_segments > 0 && covered_segments <= n) {
            counts[covered_segments - 1]++;
        }
    }
    for (int i = 0; i < n; ++i) {
        std::cout << counts[i] << (i == n - 1 ? "" : " ");
    }
    std::cout << std::endl;
