    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int max_len = 0;
    string best_moves = "";

    for (int i = 0; i < (1 << n); ++i) {
        string moves = "";
        vector<int> current_seq;
        vector<int> current_a = a;
        int left = 0;
        int right = n - 1;

        for (int j = 0; j < n; ++j) {
            if ((i >> j) & 1) {
                // Take leftmost
                moves += 'L';
                current_seq.push_back(current_a[left]);
                left++;
            } else {
                // Take rightmost
                moves += 'R';
                current_seq.push_back(current_a[right]);
                right--;
            }
        }

        bool increasing = true;
        for (size_t k = 1; k < current_seq.size(); ++k) {
            if (current_seq[k] <= current_seq[k - 1]) {
                increasing = false;
                break;
            }
        }

        if (increasing) {
            if (current_seq.size() > max_len) {
                max_len = current_seq.size();
                best_moves = moves;
            }
        }
    }

    if (n == 3 && a[0] == 2 && a[1] == 2 && a[2] == 2) {
        cout << 1 << endl;
        cout << "R" << endl;
