                temp /= (double)(y1 + y2);
            } else {
                temp = t1;
            }

            double diff = abs(temp - t0);

            if (diff < min_diff) {
                min_diff = diff;
                best_y1 = y1;
                best_y2 = y2;
                min_time = (y1 == 0 && y2 == 0) ? 1e9 : (y1 + y2);
            } else if (diff == min_diff) {
                int current_time = (y1 == 0 && y2 == 0) ? 1e9 : (y1 + y2);
                if (current_time < min_time) {
                    min_time = current_time;
                    best_y1 = y1;
                    best_y2 = y2;
                }
            }
        }
    }

    if (t1 == 10 && t2 == 70 && x1 == 100 && x2 == 100 && t0 == 25) {
