        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }

        int max_mex_sum = 0;
        for (int i = 0; i < (1 << n); ++i) {
            vector<int> A;
            vector<int> B;
            map<int, int> counts;
            for (int j = 0; j < n; ++j) {
                counts[a[j]]++;
            }

            for (int j = 0; j < n; ++j) {
                if ((i >> j) & 1) {
                    A.push_back(a[j]);
                } else {
                    B.push_back(a[j]);
                }
            }

            map<int, int> counts_A;
            for (int x : A) {
                counts_A[x]++;
            }
            map<int, int> counts_B;
            for (int x : B) {
                counts_B[x]++;
            }

            bool valid = true;
            for (auto const& [num, count] : counts) {
                int count_A = counts_A.count(num) ? counts_A[num] : 0;
